    return '<aside class="growth-ai"><div class="growth-ai-head"><span class="growth-avatar">✦</span><div><b>AI 运营总监</b><small>当前上下文：'+rangeLabel()+' · '+pageName()+'</small></div><button style="margin-left:auto;border:0;background:transparent" data-action="new-chat" title="新对话">↻</button><button style="border:0;background:transparent" data-action="toggle-ai">×</button></div><div class="growth-ai-body" id="ai-body"><div class="growth-ai-message"><span class="growth-avatar">✦</span><div class="growth-ai-bubble">我会引用当前 '+rangeLabel()+' 的数据，先说明发现，再给原因、策略和可执行 Action。</div></div>'+(store.ai.messages.length?'':'<div class="growth-quick">'+quick.map(function(q){return '<button data-ai-question="'+esc(q)+'">'+esc(q)+'</button>'}).join('')+'</div>')+store.ai.messages.map(messageHtml).join('')+'</div><div class="growth-ai-composer"><textarea id="ai-input" placeholder="问问你的 AI 运营总监…"></textarea><button data-action="send-ai">发送</button></div></aside>';
