    css();
    root.innerHTML='<div class="growth-shell '+(ui.aiOpen?'':'ai-collapsed')+'">'+nav()+'<main class="growth-main">'+topbar()+'<div class="growth-body">'+page()+'</div></main>'+(ui.aiOpen?aiPanel():'')+'</div><div id="growth-drawer"></div>';
